mapper.select:
select id, type, title, title_en, cover_image, tag, tag_en, featured, created_at, updated_at, link_type, link_url, author, duration, grade, summary, summary_en, content from aiedu_resource
and type = #{type,jdbcType=VARCHAR}
and ( title like concat('%',#{titleOrTitleEn,jdbcType=VARCHAR},'%') or title_en like concat('%',#{titleOrTitleEn,jdbcType=VARCHAR},'%') )
